style.css:
/* Upper East Side ♛ — chic preppy luxury */

* {
    scrollbar-color: #8b1e3f #f4efe8 !important;
}

body {
    background: #f4efe8 !important;
    color: #241f20 !important;
    font-family: Georgia, "Times New Roman", serif !important;
}

a {
    color: #8b1e3f !important;
}

a:hover {
    color: #b58b45 !important;
    text-decoration: none !important;
}

/* Elegant cards / panels */
div,
section,
article {
    border-radius: 8px !important;
}

/* Buttons */
button {
    background: #241f20 !important;
    color: #f8f3eb !important;
    border: 1px solid #b58b45 !important;
    border-radius: 5px !important;
    font-family: Georgia, serif !important;
}

button:hover {
    background: #8b1e3f !important;
    color: white !important;
}

/* Inputs */
input,
textarea,
select {
    background: #fffaf3 !important;
    color: #241f20 !important;
    border: 1px solid #c9b9a5 !important;
    border-radius: 5px !important;
}

/* Selection */
::selection {
    background: #8b1e3f !important;
    color: #fffaf3 !important;
}

/* Subtle gold details */
hr {
    border-color: #b58b45 !important;
}
